parameters.jsCode:
const body = $input.first().json.body;

const staticData = $getWorkflowStaticData('global');
staticData.title = body.title;
staticData.chunks = body.chunks;

return body.chunks.map(chunk => ({
  json: {
    chunk_number: chunk.chunk_number,
    script: chunk.script,
    image_prompt: chunk.image_prompt,
    duration_seconds: chunk.duration_seconds,
    scene_image_url: chunk.scene_image_url
  }
}));

const items = $input.all();

let chunkList = '';
for (const item of items) {
  const c = item.json;
  chunkList += 'Scene ' + c.chunk_number + ':\n';
  chunkList += 'Script: ' + c.script + '\n';
  chunkList += 'Image description: ' + c.image_prompt + '\n';
  chunkList += 'Duration: ' + c.duration_seconds + 's\n\n';
}

return [{
  json: {
    chunk_count: items.length,
    chunk_list: chunkList
  }
}];

parameters.text:
=I have {{ $json.chunk_count }} scenes. Write a video animation prompt and shortened narration for each.

{{ $json.chunk_list }}

Respond in this EXACT JSON format:
{
  "scenes": [
    {
      "chunk_number": 1,
      "video_prompt": "Use the provided image as the first frame. ...",
      "narration": "shortened narration here"
    }
  ]
}

parameters.jsCode:
const items = $input.all();

return items.map((item, i) => ({
  json: {
    chunk_number: i + 1,
    audio_url: item.json.secure_url
  }
}));

const audioItems = $input.all();
const chunkItems = $('Split Video Chunks').all();

if (!chunkItems || chunkItems.length === 0) {
  throw new Error('No chunks found from "Split Video Chunks".');
}
if (!audioItems || audioItems.length === 0) {
  throw new Error('No audio found.');
}

const staticData = $getWorkflowStaticData('global');
const title = staticData.title ?? chunkItems[0]?.json?.title ?? 'Untitled';

const scenes = chunkItems.map((chunkItem, i) => ({
  chunk_number: chunkItem.json.chunk_number,
  duration_seconds: chunkItem.json.duration_seconds,
  scene_image_url: chunkItem.json.scene_image_url,
  audio_url: audioItems[i]?.json?.audio_url ?? null
}));

return [{
  json: {
    title: title,
    scenes: scenes
  }
}];

const data = $input.first().json;

let currentTime = 0;
const videoClips = [];
const audioClips = [];

const effects = ["zoomIn", "zoomOut", "slideLeft", "slideRight", "slideUp", "slideDown"];

for (let i = 0; i < data.scenes.length; i++) {
  const scene = data.scenes[i];
  const effect = effects[i % effects.length];

  videoClips.push({
    asset: {
      type: "image",
      src: scene.scene_image_url
    },
    start: currentTime,
    length: scene.duration_seconds,
    effect: effect
  });

  audioClips.push({
    asset: {
      type: "audio",
      src: scene.audio_url,
      volume: 1
    },
    start: currentTime,
    length: "auto"
  });

  currentTime += scene.duration_seconds;
}

return [{
  json: {
    body: JSON.stringify({
      timeline: {
        tracks: [
          { clips: videoClips },
          { clips: audioClips }
        ]
      },
      output: {
        format: "mp4",
        resolution: "hd"
      }
    })
  }
}];

const scenes = $('Generate Video Prompts').first().json.output.scenes;

return scenes.map(scene => ({
  json: {
    chunk_number: scene.chunk_number,
    narration: scene.narration,
    body: JSON.stringify({
      text: scene.narration,
      model_id: "eleven_multilingual_v2",
      voice_settings: {
        stability: 0.6,
        similarity_boost: 0.75,
        style: 0.7,
        use_speaker_boost: true
      }
    })
  }
}));

